import org.jsoup.Connection;
import org.jsoup.nodes.*;
import org.jsoup.parser.Parser;
import org.junit.Test;
import static org.junit.Assert.*;

public class DocumentTest {
    @Test
    public void createShellTest() {
        String baseUri = "http://example.com";
        Document doc = Document.createShell(baseUri);
        assertEquals(baseUri, doc.location());
        assertNotNull(doc.head());
        assertNotNull(doc.body());
    }

    @Test
    public void locationTest() {
        String baseUri = "http://example.com";
        Document doc = new Document(baseUri);
        assertEquals(baseUri, doc.location());
    }

    @Test
    public void connectionTest() {
        // Just test if connection() works without exceptions.
        new Document("http://example.com").connection();
    }

    @Test
    public void headTest() {
        Document doc = Document.createShell("http://example.com");
        assertNotNull(doc.head());
    }

    @Test
    public void bodyTest() {
        Document doc = Document.createShell("http://example.com");
        assertNotNull(doc.body());
    }

    @Test
    public void titleTest() {
        String title = "Test Title";
        Document doc = Document.createShell("http://example.com");
        doc.title(title);
        assertEquals(title, doc.title());
    }

    @Test
    public void createElementTest() {
        Document doc = new Document("http://example.com");
        Element element = doc.createElement("div");
        assertEquals("div", element.tagName());
    }

    @Test
    public void outerHtmlTest() {
        String html = "<html><head></head><body></body></html>";
        Document doc = new Document("http://example.com");
        assertEquals(html, doc.outerHtml().trim());
    }

    @Test
    public void textTest() {
        String testText = "Test Text";
        Document doc = new Document("http://example.com");
        doc.text(testText);
        assertEquals(testText, doc.text());
    }

    @Test
    public void nodeNameTest() {
        Document doc = new Document("http://example.com");
        assertEquals("#document", doc.nodeName());
    }

    @Test
    public void charsetTest() {
        Document doc = new Document("http://example.com");
        doc.charset(Charset.forName("UTF-8"));
        assertEquals(Charset.forName("UTF-8"), doc.charset());
    }

    @Test
    public void cloneTest() {
        Document doc = new Document("http://example.com");
        Document clone = doc.clone();
        assertNotSame(doc, clone);
        assertEquals(doc.outerHtml(), clone.outerHtml());
    }

    @Test
    public void shallowCloneTest() {
        Document doc = new Document("http://example.com");
        Document clone = doc.shallowClone();
        assertNotSame(doc, clone);
        assertEquals(doc.outerHtml(), clone.outerHtml());
    }

    @Test
    public void quirksModeTest() {
        Document doc = new Document("http://example.com");
        doc.quirksMode(Document.QuirksMode.quirks);
        assertEquals(Document.QuirksMode.quirks, doc.quirksMode());
    }

    @Test
    public void parserTest() {
        Document doc = new Document("http://example.com");
        Parser parser = Parser.htmlParser();
        doc.parser(parser);
        assertEquals(parser, doc.parser());
    }

    @Test
    public void updateMetaCharsetElementTest() {
        Document doc = new Document("http://example.com");
        doc.updateMetaCharsetElement(true);
        assertEquals(true, doc.updateMetaCharsetElement());
    }
}
